describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 2000, costCents: 1000 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 10.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, 10.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const sut = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(sut.computeShippingCents([], 1_000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams set)", () => {
      expect(
        sut.computeShippingCents([makeLine("a", undefined, 2)], 1_000),
      ).toBe(0);
    });

    it("selects lowest bracket for weight within first bracket", () => {
      // 250g fits in ≤500g bracket → 300
      expect(
        sut.computeShippingCents([makeLine("a", 250, 1)], 1_000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g exactly → ≤500g bracket → 300
      expect(
        sut.computeShippingCents([makeLine("a", 500, 1)], 1_000),
      ).toBe(300);
    });

    it("selects next bracket just above boundary", () => {
      // 501g → ≤1000g bracket → 600
      expect(
        sut.computeShippingCents([makeLine("a", 501, 1)], 1_000),
      ).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g → ≤2000g bracket → 1000
      expect(
        sut.computeShippingCents([makeLine("a", 2000, 1)], 1_000),
      ).toBe(1_000);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // 3000g exceeds all brackets → overflow defaults to last bracket cost 1000
      expect(
        sut.computeShippingCents([makeLine("a", 3000, 1)], 1_000),
      ).toBe(1_000);
    });

    it("uses explicit overflow cost when provided", () => {
      const withOverflow = new WeightBasedShippingCalculator(brackets, 1_500);
      expect(
        withOverflow.computeShippingCents([makeLine("a", 3000, 1)], 1_000),
      ).toBe(1_500);
    });

    it("sums weight across multiple lines", () => {
      // 300 * 2 + 200 * 1 = 800g → ≤1000g bracket → 600
      const lines: CartLine[] = [
        makeLine("a", 300, 2),
        makeLine("b", 200, 1),
      ];
      expect(sut.computeShippingCents(lines, 1_000)).toBe(600);
    });

    it("handles unsorted brackets correctly (sorts internally)", () => {
      const unsorted: WeightBracket[] = [
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 1_000),
      ).toBe(300);
    });
  });
});

