    expect(result.lines[0]!.product.unitPriceCents).toBe(1_500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("w");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("out of stock");
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes inventory check when available and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2_000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w", 2);
  });

  it("uses asyncTaxProvider to compute tax when supplied", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy: mockDiscount, region: "US-CA" });
    cart.add(widget, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10% of 1000 = 100
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("composes price refresh + inventory + async tax + discount + shipping", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
      region: "FR",
    });
    cart.add(widget, 2); // original subtotal 2000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1_200), // refreshed: 1200 * 2 = 2400
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2), // 20% of (2400-200)=2200 → 440
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    expect(result.totals.subtotalCents).toBe(2_400);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(440);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2_200 + 440 + 500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates inventoryChecker rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockRejectedValue(new Error("inventory service down")),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      "inventory service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("first failing inventory line wins", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "gadget gone" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("g");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const sut = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(sut.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const sut = new PercentageDiscountPolicy(10);
      expect(sut.computeDiscountCents(10_000)).toBe(1_000);
    });

    it("rounds down to nearest cent", () => {
      // 33% of 100 = 33.00; 33% of 101 = 33.33 → 33
      const sut = new PercentageDiscountPolicy(33);
      expect(sut.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new PercentageDiscountPolicy(50);
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new PercentageDiscountPolicy(50);
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount returns the full subtotal", () => {
      const sut = new PercentageDiscountPolicy(100);
      expect(sut.computeDiscountCents(5_000)).toBe(5_000);
    });

    it("0% discount returns 0", () => {
      const sut = new PercentageDiscountPolicy(0);
      expect(sut.computeDiscountCents(5_000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns amountCents when subtotal exceeds it", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(1_000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(2_000);
      expect(sut.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new FixedAmountDiscountPolicy(500);
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const sut = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum = 300
      expect(sut.computeDiscountCents(1_000)).toBe(300);
    });

    it("each policy sees the original subtotal (not reduced)", () => {
      const p1 = new PercentageDiscountPolicy(50); // 500
      const p2 = new PercentageDiscountPolicy(50); // 500
      const sut = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum mode: 500 + 500 = 1000 (may exceed subtotal; caller clamps)
      expect(sut.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(sut.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const sut = new CompositeDiscountPolicy([p1, p2]);
      expect(sut.computeDiscountCents(1_000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // Start: 1000
      // p1: 10% of 1000 = 100 → remaining 900
      // p2: fixed 200 → remaining 700
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const sut = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(sut.computeDiscountCents(1_000)).toBe(300);
    });

    it("order matters: changing policy order yields different result", () => {
      // Start: 1000
      // p2 first: fixed 200 → remaining 800
      // p1 second: 10% of 800 = 80 → remaining 720
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const sut = new CompositeDiscountPolicy([p2, p1], "chain");
      expect(sut.computeDiscountCents(1_000)).toBe(280);
    });

    it("stops giving discounts when remaining reaches 0", () => {
      const p1 = new FixedAmountDiscountPolicy(600);
      const p2 = new FixedAmountDiscountPolicy(600);
      const sut = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1 takes 600 → remaining 400; wait p1 = min(600, 1000) = 600
      // remaining = 400; p2 = min(600, 400) = 400; remaining = 0
      expect(sut.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });
  });
});

