describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects invalid defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in the rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, SE: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const sut = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses regional rate when region matches", () => {
      // 0.0875 * 10000 = 875
      expect(sut.computeTaxCents(10_000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 0.05 * 10000 = 500
      expect(sut.computeTaxCents(10_000, "AU")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 0.0875 * 999 = 87.4125 → 87
      expect(sut.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("returns 0 for zero taxable", () => {
      expect(sut.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(sut.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("uses default rate of 0 when not specified", () => {
      const calc = new RegionalTaxCalculator({});
      expect(calc.computeTaxCents(10_000, "ZZ")).toBe(0);
    });
  });
});

