import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1_000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const sut = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(sut.computeShippingCents([makeLine("a", 500, 2)], 5_000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(sut.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts 0 for flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flatCents for non-empty cart", () => {
      const sut = new FlatShippingCalculator(599);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 2_000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const sut = new FlatShippingCalculator(599);
      expect(sut.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal equals freeOverCents threshold", () => {
      const sut = new FlatShippingCalculator(599, 5_000);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 5_000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
      const sut = new FlatShippingCalculator(599, 5_000);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 6_000)).toBe(0);
    });

    it("returns flatCents when subtotal is below freeOverCents threshold", () => {
      const sut = new FlatShippingCalculator(599, 5_000);
      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 4_999)).toBe(599);
    });

    it("returns flatCents when no freeOverCents is set", () => {
      const sut = new FlatShippingCalculator(599);
      expect(
        sut.computeShippingCents([makeLine("a", 100, 1)], 100_000),
      ).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 2000, costCents: 1000 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 10.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, 10.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const sut = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(sut.computeShippingCents([], 1_000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams set)", () => {
      expect(
        sut.computeShippingCents([makeLine("a", undefined, 2)], 1_000),
      ).toBe(0);
    });

    it("selects lowest bracket for weight within first bracket", () => {
      // 250g fits in ≤500g bracket → 300
      expect(
        sut.computeShippingCents([makeLine("a", 250, 1)], 1_000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g exactly → ≤500g bracket → 300
      expect(
        sut.computeShippingCents([makeLine("a", 500, 1)], 1_000),
      ).toBe(300);
    });

    it("selects next bracket just above boundary", () => {
      // 501g → ≤1000g bracket → 600
      expect(
        sut.computeShippingCents([makeLine("a", 501, 1)], 1_000),
      ).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g → ≤2000g bracket → 1000
      expect(
        sut.computeShippingCents([makeLine("a", 2000, 1)], 1_000),
      ).toBe(1_000);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // 3000g exceeds all brackets → overflow defaults to last bracket cost 1000
      expect(
        sut.computeShippingCents([makeLine("a", 3000, 1)], 1_000),
      ).toBe(1_000);
    });

    it("uses explicit overflow cost when provided", () => {
      const withOverflow = new WeightBasedShippingCalculator(brackets, 1_500);
      expect(
        withOverflow.computeShippingCents([makeLine("a", 3000, 1)], 1_000),
      ).toBe(1_500);
    });

    it("sums weight across multiple lines", () => {
      // 300 * 2 + 200 * 1 = 800g → ≤1000g bracket → 600
      const lines: CartLine[] = [
        makeLine("a", 300, 2),
        makeLine("b", 200, 1),
      ];
      expect(sut.computeShippingCents(lines, 1_000)).toBe(600);
    });

    it("handles unsorted brackets correctly (sorts internally)", () => {
      const unsorted: WeightBracket[] = [
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 1_000),
      ).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available fields", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err).toBeInstanceOf(Error);
  });

  it("handles undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "b", name: "Gadget", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates prices from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves product properties other than unitPriceCents", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(
      [{ product: { id: "x", name: "X", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 }],
      fetcher,
    );
    expect(result[0]!.product.name).toBe("X");
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart, type CartConfig } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const widget: Product = { id: "w", name: "Widget", unitPriceCents: 1_000 };
const gadget: Product = { id: "g", name: "Gadget", unitPriceCents: 2_000, weightGrams: 500 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product and tracks quantity", () => {
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("w");
    expect(snap[0]!.quantity).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -10 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(widget, 1);
    expect(cart.remove("w")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity for an existing product", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(widget, 3);
    cart.updateQuantity("w", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "not in the cart",
    );
  });

  it("clear removes all items", () => {
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy (mutations do not affect cart)", () => {
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    const snap2 = cart.snapshot();
    expect(snap2[0]!.quantity).toBe(1);
    expect(snap2[0]!.product.unitPriceCents).toBe(1_000);
  });
});

describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4_000);
  });

  it("defaults to no discount, no tax, free shipping", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1_000);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(500);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1_000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps over-subtotal discount to subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9_999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1_000);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(widget, 1); // subtotal 1000, discount 200, discounted 800
    const t = cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(t.taxCents).toBe(80);
  });

  it("shipping receives lines and discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(widget, 1); // subtotal 1000, discounted 900
    const t = cart.totals();
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
    expect(t.shippingCents).toBe(599);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    // discounted = 800, tax = 80, shipping = 500
    expect(t.totalCents).toBe(800 + 80 + 500);
  });

  it("clamps negative tax to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default region US when none provided", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(widget, 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1_000, "US");
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

describe("Cart — async checkout", () => {
