const gadget: Product = { id: "g", name: "Gadget", unitPriceCents: 2_000, weightGrams: 500 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product and tracks quantity", () => {
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("w");
    expect(snap[0]!.quantity).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -10 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(widget, 1);
    expect(cart.remove("w")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity for an existing product", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(widget, 3);
    cart.updateQuantity("w", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "not in the cart",
    );
  });

  it("clear removes all items", () => {
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy (mutations do not affect cart)", () => {
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    const snap2 = cart.snapshot();
    expect(snap2[0]!.quantity).toBe(1);
    expect(snap2[0]!.product.unitPriceCents).toBe(1_000);
  });
});

describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4_000);
  });

  it("defaults to no discount, no tax, free shipping", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1_000);
  });

  it("applies discount policy and clamps to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(500);
    expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1_000);
  });

  it("clamps negative discount to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps over-subtotal discount to subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9_999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(widget, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1_000);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      region: "US-CA",
    });
    cart.add(widget, 1); // subtotal 1000, discount 200, discounted 800
    const t = cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(t.taxCents).toBe(80);
  });

  it("shipping receives lines and discounted subtotal", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
    });
    cart.add(widget, 1); // subtotal 1000, discounted 900
    const t = cart.totals();
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      900,
    );
    expect(t.shippingCents).toBe(599);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(widget, 1); // subtotal 1000
    const t = cart.totals();
    // discounted = 800, tax = 80, shipping = 500
    expect(t.totalCents).toBe(800 + 80 + 500);
  });

  it("clamps negative tax to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default region US when none provided", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(widget, 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1_000, "US");
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

describe("Cart — async checkout", () => {
  it("returns totals and lines for basic checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2_000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(widget, 1); // original price 1000
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1_500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1_500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1_500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("w");
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w");
      expect(ie.requested).toBe(5);
      expect(ie.message).toBe("out of stock");
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("w");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes inventory check when available and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2_000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w", 2);
  });

  it("uses asyncTaxProvider to compute tax when supplied", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ discountPolicy: mockDiscount, region: "US-CA" });
    cart.add(widget, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10% of 1000 = 100
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("composes price refresh + inventory + async tax + discount + shipping", async () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      shippingCalculator: mockShipping,
      region: "FR",
    });
    cart.add(widget, 2); // original subtotal 2000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1_200), // refreshed: 1200 * 2 = 2400
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2), // 20% of (2400-200)=2200 → 440
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    expect(result.totals.subtotalCents).toBe(2_400);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(440);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2_200 + 440 + 500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates inventoryChecker rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockRejectedValue(new Error("inventory service down")),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      "inventory service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("first failing inventory line wins", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "gadget gone" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("g");
    }
  });
});
"}

