toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const sut = new NoTaxCalculator();

  it.each([
    [1_000, "US"],
    [0, "FR"],
    [-100, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(sut.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects invalid defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in the rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, SE: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const sut = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses regional rate when region matches", () => {
      // 0.0875 * 10000 = 875
      expect(sut.computeTaxCents(10_000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 0.05 * 10000 = 500
      expect(sut.computeTaxCents(10_000, "AU")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 0.0875 * 999 = 87.4125 → 87
      expect(sut.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("returns 0 for zero taxable", () => {
      expect(sut.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(sut.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("uses default rate of 0 when not specified", () => {
      const calc = new RegionalTaxCalculator({});
      expect(calc.computeTaxCents(10_000, "ZZ")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("resolves tax using the provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    const result = await sut.computeTaxCents(1_000, "US");
    expect(result).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const sut = new AsyncTaxCalculator(provider);
    // 0.0875 * 999 = 87.4125 → 87
    expect(await sut.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(0, "US")).toBe(0);
    // Provider should not be called when taxable is 0
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1_000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1_000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1_000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1_000, "US")).rejects.toThrow(
      "network error",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 500 }, quantity: 3 },
    ];
    // 200*2 + 500*3 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1_900);
  });

  it("treats undefined weight as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

