+
+    it("returns 0 when subtotal equals freeOverCents threshold", () => {
+      const sut = new FlatShippingCalculator(599, 5_000);
+      expect(sut.computeShippingCents([makeLine("a", 100, 1)], 5_000)).toBe(0);
+    });
+
